var WS_WORDS=['planet','guitar','window','pencil','orange','castle','silver','bottle','rocket','flower','monkey','puzzle','dragon','glass','ribbon','thunder','jungle','candle','bridge','shadow'];
function shuffleArr(a){ a=a.slice(); for(var i=a.length-1;i>0;i--){ var j=Math.floor(Math.random()*(i+1)); var t=a[i];a[i]=a[j];a[j]=t; } return a; }
function scramble(word){ var s; var guard=0; do{ s=shuffleArr(word.split('')).join(''); guard++; }while(s===word && guard<20); return s; }
function check(orig, guess){ return orig.toLowerCase()===String(guess||'').toLowerCase(); }
var EXPORTS={scramble:scramble,check:check,WS_WORDS:WS_WORDS,shuffleArr:shuffleArr};


if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.WordScrambleForgePure = EXPORTS; }
